import json
from datetime import datetime

from pyvkteamsclient.admin.base.client import BaseAdminClient
from pyvkteamsclient.tracer import tracer


class UsersMethods(BaseAdminClient):
    @tracer.start_as_current_span("admin.users.api_users")
    def api_users(
        self,
        filter_name: str,
        domains: list[str],
        filter_offset: int = 0,
        filter_limit: int = 5,
        filter_blocked: bool = True,
        filter_never_went: bool = True,
        filter_last_activity: int = int(datetime.now().timestamp()),
        sort: list[str] = ("name", "DESC"),
    ):
        """
        Запрос списка пользователей
        :param filter_blocked: показать только заблокированных
        :param filter_never_went: показать только тех, кто никогда не заходил
        :param filter_last_activity: фильтр по unixtime
        :param filter_name: фильтрация по имени пользователя и email
        :param filter_offset: офсет
        :param filter_limit: лимит пользователей
        :param sort: Поля по которым возможны сортировка и направление сортировки
        :param domains: Домены пользователей, включаемые в поиск
        :return: тело ответа сервера
        """
        return self.get(
            path="api/users",
            filter=json.dumps(
                {
                    "offset": filter_offset,
                    "limit": filter_limit,
                    "blocked": filter_blocked,
                    "never_went": filter_never_went,
                    "last_activity": filter_last_activity,
                    "name": filter_name,
                },
            ),
            sort=json.dumps(sort),
            domains=json.dumps(domains),
        )

    @tracer.start_as_current_span("admin.users.api_users_user_id")
    def api_users_user_id(self, user_id: str):
        """
        Запрос пользователя по ID
        :param user_id: id пользователя
        :return: тело ответа сервера
        """
        return self.get(path=f"api/users/{user_id}")

    @tracer.start_as_current_span("admin.users.api_users_user_id_chats")
    def api_users_user_id_chats(
        self,
        user_id: str,
        filter_name: str,
        filter_group: bool,
        filter_channel: bool,
    ):
        """
        Запрос чатов пользователя по ID пользователя
        :param user_id: id пользователя
        :param filter_name: фильтрация по имени пользователя и email
        :param filter_group: показать группы
        :param filter_channel: показать каналы.
        :return: тело ответа сервера
        """
        return self.get(
            path=f"api/users/{user_id}/chats",
            filter=json.dumps(
                {
                    "groups": filter_group,
                    "channel": filter_channel,
                    "name": filter_name,
                },
            ),
        )

    @tracer.start_as_current_span("admin.users.api_users_user_id_sessions")
    def api_users_user_id_sessions(self, user_id: str):
        """
        Запрос сессий пользователя по ID пользователя
        :param user_id: id пользователя
        :return: тело ответа сервера
        """
        return self.get(path=f"api/users/{user_id}/sessions")

    @tracer.start_as_current_span("admin.users.api_users_user_id_sessions_hash_reset")
    def api_users_user_id_sessions_hash_reset(self, user_id: str, session_id: str):
        """
        Ресет сессии
        :param user_id: id пользователя
        :param session_id: id сессии
        :return: тело ответа сервера
        """
        return self.post(path=f"api/users/{user_id}/sessions/{session_id}/reset")

    @tracer.start_as_current_span("admin.users.api_users_user_id_reset_all_sessions")
    def api_users_user_id_reset_all_sessions(self, user_id: str):
        """
        Ресет сессии
        :param user_id: id пользователя
        :return: тело ответа сервера
        """
        return self.post(path=f"api/users/{user_id}/resetAllSessions")
